package com.yuewei.plm.module.partner;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class PartnerCatalogSampleRulesTest {
 private Map<String,Object> snapshot(){var s=new LinkedHashMap<String,Object>();s.put("catalogStyleId",23L);s.put("catalogStyleCode","CP-000023");s.put("supplierCode","SUP-XD");s.put("material","TPU+PC");s.put("configuration","支架");s.put("phones",List.of(Map.of("phoneModelId",18L,"displayName","iPhone18 Pro Max"),Map.of("phoneModelId",12L,"displayName","iPhone12")));s.put("selectedPairs",List.of(Map.of("phoneModelId",18L,"colorId",5L,"colorName","黑色"),Map.of("phoneModelId",12L,"colorId",7L,"colorName","蓝色")));return s;}
 @Test void oneReceiptNeverExpandsASelectedModelAndColorIntoCartesianPairs(){var s=snapshot();assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(s,18,7));var pair=PartnerCatalogSampleRules.pair(s,18,5);assertEquals("CP:23:18:5:"+PartnerCatalogSampleRules.configurationKey(s),pair.get("catalogSpecKey"));assertEquals(List.of(18L),pair.get("phoneModelIds"));assertEquals("iPhone18 Pro Max · 黑色",pair.get("specName"));assertFalse(pair.containsKey("specId"));assertFalse(pair.containsKey("productId"));}
 @Test void missingColorAndUnselectedModelsCannotBeActualReceipt(){assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(snapshot(),18,0));assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(snapshot(),99,5));}
 @Test void priceVersionAndSelectionChangesDoNotInventANewQualityBasis(){var json=new ObjectMapper();var s=snapshot();var pair=PartnerCatalogSampleRules.pair(s,18,5);String original=PartnerCatalogSampleRules.qualityBasis(json,s,pair);s.put("unitPrice","99");s.put("sourceVersion",99);s.put("selectionVersion",99);assertEquals(original,PartnerCatalogSampleRules.qualityBasis(json,s,pair));s.put("material","不同材质");assertNotEquals(original,PartnerCatalogSampleRules.qualityBasis(json,s,pair));}
 private Map<String,Object> scope(){var p=PartnerCatalogSampleRules.pair(snapshot(),18,5);p.put("qty",2L);p.put("qualityBasis","frozen");return p;}
 private Map<String,Object> check(Map<String,Object> scope){return new LinkedHashMap<>(Map.of("date",LocalDate.now().toString(),"factory","实际供应商工厂","checks","现场检查型号、颜色与结构","result","pass","onsite",true,"scope",List.of(scope),"refs",List.of()));}
 @Test void catalogQualityUsesActualPairInsteadOfPretendingToBeSpecZero(){var scope=scope();var inputScope=new LinkedHashMap<>(scope);inputScope.put("checkedQty",2L);var result=PartnerQualityRules.result(Map.of("sourceKind","sample","allowedScope",List.of(scope)),check(inputScope));String key=PartnerValues.text(scope.get("catalogSpecKey"));assertEquals(key,PartnerQualityRules.scopeKey(PartnerValues.maps(result.get("scope")).get(0)));assertFalse(PartnerValues.maps(result.get("scope")).get(0).containsKey("specId"));assertFalse(PartnerQualityRules.passedCatalog(Map.of("status","pending_signature","resultSnapshot",result),key));assertTrue(PartnerQualityRules.passedCatalog(Map.of("status","signed","resultSnapshot",result),key));assertFalse(PartnerQualityRules.passedCatalog(Map.of("status","signed","resultSnapshot",result),"CP:23:12:7"));}
 @Test void forgedKeysUnlistedPairsAndOverCheckedQuantitiesAreRejected(){var allowed=scope();var source=Map.<String,Object>of("sourceKind","sample","allowedScope",List.of(allowed));var raw=new LinkedHashMap<>(allowed);raw.put("checkedQty",3L);assertThrows(RuntimeException.class,()->PartnerQualityRules.result(source,check(raw)));raw.put("checkedQty",1L);raw.put("colorId",7L);assertThrows(RuntimeException.class,()->PartnerQualityRules.result(source,check(raw)));raw.put("catalogSpecKey","CP:23:18:7");assertThrows(RuntimeException.class,()->PartnerQualityRules.result(source,check(raw)));}
 @Test void sampleScopeRetainsSPAndNoInventedCommercialIdentity(){var sample=scope();sample.put("id",91L);sample.put("receivedQty",2L);var scope=PartnerCatalogSampleRules.qualityScope(sample);assertEquals(91L,scope.get("sampleId"));assertEquals(2L,scope.get("qty"));assertFalse(scope.containsKey("specId"));assertFalse(scope.containsKey("productId"));}
 @Test void differentConfigurationsNeverReuseTheSameCatalogSpecKey(){var s=snapshot();var original=PartnerCatalogSampleRules.pair(s,18,5);s.put("configuration","不同结构");var changed=PartnerCatalogSampleRules.pair(s,18,5);assertNotEquals(original.get("catalogSpecKey"),changed.get("catalogSpecKey"));s.put("configKey","explicit-stable-A");var keyed=PartnerCatalogSampleRules.pair(s,18,5);s.put("configuration","同一稳定配置的材料文字更新");assertEquals(keyed.get("catalogSpecKey"),PartnerCatalogSampleRules.pair(s,18,5).get("catalogSpecKey"));}
 private Map<String,Object> pendingColor(){var s=snapshot();s.put("phoneModelIds",List.of(18L));s.put("selectedPairs",List.of());s.put("receiptColorMode","at_receipt");s.put("receiptColors",List.of(Map.of("id",5L,"name","黑色","code","SC-5","version",2L),Map.of("id",7L,"name","蓝色")));return s;}
 @Test void actualColorMayBeChosenLaterButOnlyForConfirmedPhonesAndExistingSupplierOriginalColors(){var s=pendingColor();String before=PartnerValues.signature(new ObjectMapper(),s);var actual=PartnerCatalogSampleRules.pair(s,18,7);assertEquals("蓝色",actual.get("colorName"));assertEquals(true,actual.get("colorConfirmedAtReceipt"));assertEquals("CP:23:18:7:"+PartnerCatalogSampleRules.configurationKey(s),actual.get("catalogSpecKey"));assertEquals(before,PartnerValues.signature(new ObjectMapper(),s));assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(s,12,7));assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(s,18,99));assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(s,18,0));}
 @Test void lateColorCannotBypassExplicitNonSupplyOrReinterpretAnOldDamagedSnapshot(){for(String field:List.of("unavailablePairs","supplyPairings")){var s=pendingColor();s.put(field,List.of(Map.of("phoneModelId",18L,"colorId",7L,"state","unavailable")));assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(s,18,7));}var old=pendingColor();old.remove("receiptColorMode");assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(old,18,5));var explicit=snapshot();explicit.put("receiptColorMode","at_receipt");explicit.put("receiptColors",pendingColor().get("receiptColors"));assertThrows(RuntimeException.class,()->PartnerCatalogSampleRules.pair(explicit,18,7));}
}
